101	static btn_buttonset_t sf32lb52_button_readset(void)
102	{
103	  bool level = sifli_gpio_read(SF32LB52_BUTTON_KEY2_PIN);
104	
105	#if SF32LB52_BUTTON_KEY2_ACTIVE_LOW
106	  return level ? 0 : 1;
107	#else
108	  return level ? 1 : 0;
109	#endif
110	}
111	
112	static void sf32lb52_button_interrupt(void *arg)
113	{
114	  FAR struct sf32lb52_btnlower_s *priv =
115	    (FAR struct sf32lb52_btnlower_s *)arg;
116	  btn_buttonset_t sample;
117	
118	  if (priv == NULL)
119	    {
120	      return;
121	    }
122	
123	  sample = sf32lb52_button_readset();
124	  if (sample == priv->last_sample)
125	    {
126	      return;
127	    }
128	
129	  priv->last_sample = sample;
130	
131	  if (priv->handler != NULL)
132	    {
133	      priv->handler(&priv->lower, priv->arg);
134	    }
135	}
136	
137	static void sf32lb52_button_poll(wdparm_t arg)
138	{
139	  FAR struct sf32lb52_btnlower_s *priv =
140	    (FAR struct sf32lb52_btnlower_s *)arg;
141	  btn_buttonset_t sample;
142	
143	  if (priv == NULL)
144	    {
145	      return;
146	    }
147	
148	  if (priv->poll_enabled)
149	    {
150	      sample = sf32lb52_button_readset();
151	      if (sample != priv->last_sample)
152	        {
153	          priv->last_sample = sample;
154	          if (priv->handler != NULL)
155	            {
156	              priv->handler(&priv->lower, priv->arg);
157	            }
158	        }
159	
160	      wd_start(&priv->poll_wdog, MSEC2TICK(SF32LB52_BUTTON_POLL_MS),
161	               sf32lb52_button_poll, (wdparm_t)priv);
162	    }
163	}
