177	static void sf32lb52_btn_enable(FAR const struct btn_lowerhalf_s *lower,
178	                                btn_buttonset_t press,
179	                                btn_buttonset_t release,
180	                                btn_handler_t handler,
181	                                FAR void *arg)
182	{
183	  FAR struct sf32lb52_btnlower_s *priv =
184	    (FAR struct sf32lb52_btnlower_s *)lower;
185	  btn_buttonset_t either = press | release;
186	  int ret;
187	
188	  if (either == 0 || handler == NULL)
189	    {
190	      if (priv->irq_enabled)
191	        {
192	          sifli_gpio_set_event(SF32LB52_BUTTON_KEY2_PIN, false, false,
193	                               NULL, NULL);
194	          priv->irq_enabled = false;
195	        }
196	
197	      priv->poll_enabled = false;
198	      wd_cancel(&priv->poll_wdog);
199	
200	      priv->handler = NULL;
201	      priv->arg     = NULL;
202	      return;
203	    }
204	
205	  priv->handler = handler;
206	  priv->arg     = arg;
207	  priv->last_sample = sf32lb52_button_readset();
208	
209	  if (!priv->irq_enabled)
210	    {
211	      ret = sifli_gpio_set_event(SF32LB52_BUTTON_KEY2_PIN, true, true,
212	                                 sf32lb52_button_interrupt, priv);
213	      if (ret >= 0)
214	        {
215	          priv->irq_enabled = true;
216	        }
217	      else
218	        {
219	          priv->handler = NULL;
220	          priv->arg     = NULL;
221	        }
222	    }
223	
224	  if (!priv->poll_enabled)
225	    {
226	      priv->poll_enabled = true;
227	      wd_start(&priv->poll_wdog, MSEC2TICK(SF32LB52_BUTTON_POLL_MS),
228	               sf32lb52_button_poll, (wdparm_t)priv);
229	    }
230	}
