633	
634	static int sf32lb_lcd_setpower(FAR struct lcd_dev_s *dev, int power)
635	{
636	  FAR struct sf32lb_lcd_dev_s *priv = (FAR struct sf32lb_lcd_dev_s *)dev;
637	
638	  lcdinfo("power: %d\n", power);
639	  DEBUGASSERT((unsigned)power <= CONFIG_LCD_MAXPOWER);
640	
641	  /* Set new power level */
642	
643	  if (power > 0)
644	    {
645	      /* Turn on the display */
646	
647	      if (priv->p_drv_ops && priv->p_drv_ops->p_ops &&
648	          priv->p_drv_ops->p_ops->DisplayOn)
649	        {
650	          priv->p_drv_ops->p_ops->DisplayOn(&priv->hlcdc);
651	        }
652	
653	      /* Save the power */
654	
655	      priv->power = power;
656	    }
657	  else
658	    {
659	      /* Turn off the display */
660	
661	      if (priv->p_drv_ops && priv->p_drv_ops->p_ops &&
662	          priv->p_drv_ops->p_ops->DisplayOff)
663	        {
664	          priv->p_drv_ops->p_ops->DisplayOff(&priv->hlcdc);
665	        }
666	
667	      /* Save the power */
668	
669	      priv->power = 0;
670	    }
671	
672	  return OK;
673	}
