207	static uint32_t sf32lb_pwm_gptclock(FAR GPT_HandleTypeDef *htim)
208	{
209	#ifdef SF32LB52X
210	  if (htim->Instance == hwp_gptim2)
211	    {
212	      return 24000000;
213	    }
214	#endif
215	
216	  return HAL_RCC_GetPCLKFreq(htim->core, 1);
217	}
