219	static int sf32lb_pwm_timer_config(FAR struct sf32lb_pwm_lowerhalf_s *priv,
220	                                   uint32_t frequency,
221	                                   ub16_t duty,
222	                                   uint32_t channel)
223	{
224	  FAR GPT_HandleTypeDef *tim = &priv->tim_handle;
225	  GPT_OC_InitTypeDef oc_cfg;
226	  uint32_t timclk;
227	  uint64_t ticks;
228	  uint32_t prescaler;
229	  uint32_t period;
230	  uint32_t pulse;
231	
232	  if (frequency == 0)
233	    {
234	      return -EINVAL;
235	    }
236	
237	  timclk = sf32lb_pwm_gptclock(tim);
238	  if (timclk == 0)
239	    {
240	      return -EINVAL;
241	    }
242	
243	  ticks = (uint64_t)timclk / (uint64_t)frequency;
244	  if (ticks == 0)
245	    {
246	      ticks = 1;
247	    }
248	
249	  prescaler = (uint32_t)((ticks + 65535ULL - 1ULL) / 65535ULL);
250	  if (prescaler == 0)
251	    {
252	      prescaler = 1;
253	    }
254	
255	  period = (uint32_t)(ticks / prescaler);
256	  if (period == 0)
257	    {
258	      period = 1;
259	    }
260	  else if (period > 65535)
261	    {
262	      period = 65535;
263	    }
264	
265	  pulse = (uint32_t)(((uint64_t)duty * (uint64_t)period) >> 16);
266	  if (pulse > period)
267	    {
268	      pulse = period;
269	    }
270	
271	  tim->Init.Prescaler         = prescaler - 1;
272	  tim->Init.CounterMode       = GPT_COUNTERMODE_UP;
273	  tim->Init.Period            = period - 1;
274	  tim->Init.RepetitionCounter = 0;
275	
276	  if (HAL_GPT_PWM_Init(tim) != HAL_OK)
277	    {
278	      return -EIO;
279	    }
280	
281	  oc_cfg.OCMode       = GPT_OCMODE_PWM1;
282	  oc_cfg.Pulse        = pulse;
283	  oc_cfg.OCPolarity   = GPT_OCPOLARITY_HIGH;
284	  oc_cfg.OCNPolarity  = GPT_OCNPOLARITY_LOW;
285	  oc_cfg.OCFastMode   = GPT_OCFAST_DISABLE;
286	  oc_cfg.OCIdleState  = GPT_OCIDLESTATE_RESET;
287	  oc_cfg.OCNIdleState = GPT_OCNIDLESTATE_RESET;
288	
289	  if (HAL_GPT_PWM_ConfigChannel(tim, &oc_cfg, channel) != HAL_OK)
290	    {
291	      return -EIO;
292	    }
293	
294	  return OK;
295	}
