param(
  [int]$Seconds = 45,
  [string]$Port = 'COM5',
  [int]$Baud = 1000000
)
$ErrorActionPreference = 'SilentlyContinue'
$p = New-Object System.IO.Ports.SerialPort -ArgumentList $Port,$Baud,'None',8,'One'
$p.ReadTimeout = 200
$p.Open()
$p.DtrEnable = $false
$p.RtsEnable = $false
Start-Sleep -Milliseconds 200
while ($p.BytesToRead -gt 0) { [void]$p.ReadByte() }
$bytes = New-Object System.Collections.Generic.List[byte]
$sw = [System.Diagnostics.Stopwatch]::StartNew()
$seenNsh = $false
while ($sw.ElapsedMilliseconds -lt ($Seconds * 1000)) {
  try { $bytes.Add([byte]$p.ReadByte()) } catch {}
  if (-not $seenNsh -and $bytes.Count -gt 0) {
    $txt = -join ($bytes | ForEach-Object { [char]$_ })
    if ($txt -match 'nsh>') { $seenNsh = $true }
  }
  if ($seenNsh -and $sw.ElapsedMilliseconds -gt 4000) { break }
}
$p.Close()
$out = -join ($bytes | ForEach-Object { [char]$_ })
$out = $out -replace "\x1B\[[0-9;?]*[A-Za-z]", ''
$out = $out -replace "`r", ''
Write-Output ("bytes=" + $bytes.Count)
Write-Output $out

