301	static int gpint_enable(struct gpio_dev_s *dev, bool enable)
302	{
303	  struct sifli_gpint_dev_s *gpint_dev =
304	                              (struct sifli_gpint_dev_s *)dev;
305	
306	  if (enable)
307	    {
308	      if (gpint_dev->callback != NULL)
309	        {
310	          gpioinfo("Enabling the interrupt\n");
311	
312	          /* Configure the interrupt for rising edge */
313	
314	          sifli_gpio_set_event(g_gpiointinputs[gpint_dev->sifli_gpio.id],
315	                             true, true, sifli_gpio_interrupt,
316	                             &g_gpint[gpint_dev->sifli_gpio.id]);
317	        }
318	    }
319	  else
320	    {
321	      gpioinfo("Disable the interrupt\n");
322	      sifli_gpio_set_event(g_gpiointinputs[gpint_dev->sifli_gpio.id],
323	                         false, false, NULL, NULL);
324	    }
325	
326	  return OK;
327	}
